# python
from collections import deque
from openpyxl import load_workbook
from openpyxl.utils import column_index_from_string

fp = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx'
wb = load_workbook(fp)
ws = wb.active

# Map colors and utility
def coord_to_indices(coord):
    i = 0
    while i < len(coord) and not coord[i].isdigit():
        i += 1
    col = column_index_from_string(coord[:i])
    row = int(coord[i:])
    return (row, col)

cell_map = {}
for row in ws.iter_rows():
    for cell in row:
        coord = cell.coordinate
        rgb = None
        if cell.fill and cell.fill.fgColor and cell.fill.fgColor.type == 'rgb' and cell.fill.fgColor.rgb:
            rgb = cell.fill.fgColor.rgb[-6:].upper()
        cell_map[coord_to_indices(coord)] = rgb

def is_blue(hex_color):
    if not hex_color:
        return False
    r = int(hex_color[0:2], 16)
    g = int(hex_color[2:4], 16)
    b = int(hex_color[4:6], 16)
    return b > 200 and r < 50 and g < 180

blue_indices = {pos for pos, color in cell_map.items() if is_blue(color)}

start = (1,1)
max_row, max_col = ws.max_row, ws.max_column

DIRECTIONS = {
    'up':    (-2, 0),
    'down':  (2, 0),
    'left':  (0, -2),
    'right': (0, 2)
}

queue = deque([(start[0], start[1], 0, None)])
visited = set([(start[0], start[1], 0, None)])
result_cell = None

while queue:
    r, c, moves, prev_dir = queue.popleft()
    if moves == 11:
        result_cell = (r, c)
        break
    for dname, (dr, dc) in DIRECTIONS.items():
        if prev_dir:
            if (prev_dir == 'up' and dname == 'down') or (prev_dir == 'down' and dname == 'up') or (prev_dir == 'left' and dname == 'right') or (prev_dir == 'right' and dname == 'left'):
                continue
        nr, nc = r + dr, c + dc
        if 1 <= nr <= max_row and 1 <= nc <= max_col and (nr, nc) not in blue_indices:
            state = (nr, nc, moves+1, dname)
            if state not in visited:
                visited.add(state)
                queue.append(state)

print('Result cell:', result_cell)
print('Result color:', cell_map.get(result_cell))

