# python
from collections import deque
from openpyxl import load_workbook
from openpyxl.utils import column_index_from_string

fp = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx'
wb = load_workbook(fp)
ws = wb.active
max_row, max_col = ws.max_row, ws.max_column

cell_map = {}
for row in ws.iter_rows():
    for cell in row:
        rgb = None
        if cell.fill and cell.fill.fgColor and cell.fill.fgColor.type == 'rgb' and cell.fill.fgColor.rgb:
            rgb = cell.fill.fgColor.rgb[-6:].upper()
        i=0; coord=cell.coordinate
        while i<len(coord) and not coord[i].isdigit():
            i+=1
        col = column_index_from_string(coord[:i]); row=int(coord[i:])
        cell_map[(row,col)] = rgb

def is_blue(h):
    if not h: return False
    r=int(h[0:2],16); g=int(h[2:4],16); b=int(h[4:6],16)
    return b>200 and r<50 and g<180
blue = {p for p,c in cell_map.items() if is_blue(c)}

D={'up':(-2,0),'down':(2,0),'left':(0,-2),'right':(0,2)}
start=(1,1)
q=deque([(start[0],start[1],0,None,[])])
vis=set([(start[0],start[1],0,None)])
res=None
while q:
    r,c,m,prev,path=q.popleft()
    if m==11:
        res=(r,c); break
    for name,(dr,dc) in D.items():
        if prev and ((prev=='up' and name=='down') or (prev=='down' and name=='up') or (prev=='left' and name=='right') or (prev=='right' and name=='left')):
            continue
        nr=r+dr; nc=c+dc
        if 1<=nr<=max_row and 1<=nc<=max_col and (nr,nc) not in blue:
            st=(nr,nc,m+1,name)
            if st not in vis:
                vis.add(st)
                q.append((nr,nc,m+1,name,path+[(nr,nc)]))
print('res:',res)
print('color:', cell_map.get(res))

